# BT.601 -> hardware 10-bit, luma pre-compensated 16/13 (the output stage scales luma by 13/16)
YK = 876.0 * 16.0 / 13.0 / 255.0
CK = 896.0 / 255.0
MAT = {'R': (0.299 * YK, 0.5 * CK, -0.168736 * CK),
       'G': (0.587 * YK, -0.418688 * CK, -0.331264 * CK),
       'B': (0.114 * YK, -0.081312 * CK, 0.5 * CK)}


def tables():
    w = []
    for t in (0, 1):
        for p in range(256):
            e = T_E[t][p] & 0xFFF
            w.append(((e << 4),
                      (T_A[t][p] << 8) | T_C[t][p],
                      ((T_O[t][p] & 0xFF) << 8) | T_BG[t][p],
                      (T_R[t][p] << 8) | T_BO[t][p]))
    return w


def rgb_rom(ch):
    ky, ku, kv = MAT[ch]
    out = []
    for i in range(256):
        y = int(round(ky * i)); u = int(round(ku * i)); v = int(round(kv * i))
        out.append(((y & 0x3FF) << 22) | ((u & 0x3FF) << 12) | ((v & 0x3FF) << 2))
    return out


def nose_lut():
    return [max(1, min(255, int(round(64.0 * 2.0 ** ((512.0 - 16 * k) / 300.0))))) for k in range(64)]


def write_pkg():
    L = ["-- Generated by jukebox.py -- DO NOT EDIT.",
         "library ieee;\nuse ieee.std_logic_1164.all;\nuse ieee.numeric_std.all;\n",
         "package jukebox_pkg is",
         "    type t_jb_tab is array (0 to 511) of std_logic_vector(15 downto 0);"]
    w = tables()
    for k in range(4):
        L.append("    constant C_JB_T%d : t_jb_tab := (" % k)
        L.append(",\n".join("        " + ", ".join('x"%04X"' % w[i][k] for i in range(j, j + 8)) for j in range(0, 512, 8)) + ");")
    L.append("    type t_jb_rgb is array (0 to 255) of std_logic_vector(31 downto 0);")
    for ch in 'RGB':
        r = rgb_rom(ch)
        L.append("    constant C_JB_RGB_%s : t_jb_rgb := (" % ch)
        L.append(",\n".join("        " + ", ".join('x"%08X"' % v for v in r[j:j + 4]) for j in range(0, 256, 4)) + ");")
    L.append("    type t_jb_nose is array (0 to 63) of unsigned(7 downto 0);")
    L.append("    constant C_JB_NOSE : t_jb_nose := (")
    n = nose_lut()
    L.append(",\n".join("        " + ", ".join("to_unsigned(%d, 8)" % v for v in n[j:j + 8]) for j in range(0, 64, 8)) + ");")
    L.append("end package jukebox_pkg;")
    with open(os.path.join(HERE, "jukebox_pkg.vhd"), "w") as f:
        f.write("\n".join(L) + "\n")


if __name__ == "__main__":
    write_pkg()
    print("jukebox_pkg.vhd written")
